(function(root){'use strict';const A=root.AIBrain=root.AIBrain||{};A.rankKnowledge=function(query,entries,route={},opts={}){const text=A.norm(query),labels=new Set((route.labels||[]).map(x=>x.id)),aliases=new Set((route.aliases||[]).map(x=>x.canonical)),max=opts.maxResults||12;return(entries||[]).map(e=>{let score=0,reasons=[];const fields=[e.title,e.path,...(e.tags||[]),...(e.capabilities||[]),...(e.domains||[])].filter(Boolean).join(' ');const lexical=A.scoreTerms(text,A.tokens(fields));if(lexical){score+=lexical;reasons.push('lexical')}for(const d of e.domains||[])if(labels.has(d)||aliases.has(d)){score+=6;reasons.push('domain:'+d)}for(const c of e.capabilities||[])if(labels.has(c)||aliases.has(c)){score+=5;reasons.push('capability:'+c)}if(e.priority)score+=Number(e.priority)||0;if(e.negativeTriggers&&e.negativeTriggers.some(t=>text.includes(A.norm(t)))){score-=10;reasons.push('negative trigger')}return{entry:e,score,reasons}}).filter(x=>x.score>0).sort((a,b)=>b.score-a.score).slice(0,max);};})(typeof globalThis!=='undefined'?globalThis:this);
